layers.vertex:
attribute vec3 aO; attribute float aT, aK; attribute vec4 aD; uniform float uTime; varying vec2 vP; varying float vU, vK, vS;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 0.42){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vS = aD.w; vP = position.xy;
      if (aK < 1.5){                                              // sweep: horizontal ring around the body (chest / waist)
        float S = 1.35; vP = position.xy*S;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, aD.z, -position.y*S), 1.); return; }
      if (aK < 2.5){                                              // fragment: leaves the body surface, pushed outward, slight drop
        float t = clamp((u - .03)/.31, 0., 1.), k = 1. - pow(1. - t, 3.);
        vec3 dir = vec3(aD.x, 0., aD.y);
        vec3 p = aO + dir*(.24 + .95*k) + vec3(0., aD.z + .18*k - .35*t*t, 0.);
        float rot = aD.w*6.28 + k*2.4*(aD.w > .5 ? 1. : -1.), c = cos(rot), s = sin(rot);
        vec4 mv = viewMatrix*vec4(p, 1.); mv.xy += mat2(c, -s, s, c)*position.xy*.18*(1. - .25*t); gl_Position = projectionMatrix*mv; return; }
      vec4 mv = viewMatrix*vec4(aO + vec3(0., aD.z, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.3;   // core flash + vertical stroke
      vP = position.xy*vec2(.5, 1.); mv.xy += position.xy*vec2(.3, .6)*aD.w; gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform vec3 uA, uB; varying vec2 vP; varying float vU, vK, vS;
    float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5453); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h2(i), h2(i + vec2(1,0)), f.x), mix(h2(i + vec2(0,1)), h2(i + vec2(1,1)), f.x), f.y); }
    void main(){
      vec3 hot = mix(uB, vec3(1., .97, .92), .35), rgb = vec3(0.); float al = 0.;
      if (vK < 1.5){
        // centre → out: four wide calligraphic arcs (thin tips, full middle) that open with the sweep and thin out as they go
        float dl = vK > .5 ? .04 : 0., t = clamp((vU - dl)/.3, 0., 1.);
        float r = length(vP), a = atan(vP.y, vP.x) + .45 + vK*.8 + t*.35;
        float R = mix(.16, 1.18 - .18*vK, 1. - pow(1. - t, 3.));
        float sg = fract(a/6.28318*4.), s = clamp((sg - .07)/.86, 0., 1.), taper = pow(sin(3.14159*s), .6);
        float w = (.01 + .03*taper)*(1. - .55*t);
        float line = exp(-pow((r - R)/w, 2.))*taper, core = lcore(r - R, w*.3)*taper;
        float wash = exp(-pow((r - R*.82)/.16, 2.))*.07*smoothstep(0., .3, t);   // a faint wake behind the front
        float f = pow(1. - t, 1.3)*(vU - dl < .033 ? 1.5 : 1.)*step(0., vU - dl)*(1. - .35*vK);
        rgb = (uA*(line*.95 + wash) + hot*core*.8)*f*smoothstep(1.35, 1.2, r);
      } else if (vK < 2.5){
        // dark broken piece of a constricting mark: bent sliver, sharp ends; erodes with a thin hot rim at the break front
        float t = clamp((vU - .03)/.31, 0., 1.);
        vec2 q = vP; float d = abs(length(q - vec2(0., -1.)) - 1.), m = smoothstep(.72, .5, abs(q.x));
        float body = exp(-pow(d/.16, 2.))*m;
        float n = vn(q*2.6 + vS*37.), thr = -.1 + 1.15*t;               // alpha erosion
        float alive = smoothstep(thr, thr + .1, n), front = exp(-pow((n - thr)/.07, 2.))*step(.02, t);
        float snap = vU < .066 ? 1. : 0.;                                // the break: 2 frames of hot outline
        al = body*alive*.62*(1. - t*t);
        rgb = (uA*front*1.3 + hot*snap*.9)*body*(1. - t) + uA*exp(-pow(d/.05, 2.))*m*alive*.18*(1. - t);
      } else {
        // core flash (2-frame peak) + the icon's thin vertical stroke through the chest, thin at both ends
        float L = .22, t = clamp(vU/L, 0., 1.); if (vU > L) discard;
        vec2 p = vP; float r = length(p*vec2(1., 2.));
        float glow = exp(-r*r*14.)*(.55 + (vU < .033 ? 1.1 : 0.)), ys = clamp(abs(p.y), 0., 1.);
        float stroke = exp(-pow(p.x/(.018 + .03*(1. - ys)), 2.))*pow(max(1. - ys, 0.), .7)*1.1;
        float f = pow(1. - t, 1.6);
        rgb = (uA*(glow*.8 + stroke*.6) + hot*(stroke*.7 + exp(-r*r*60.)*.9))*f*smoothstep(1., .85, max(abs(p.x)*2., abs(p.y)));
      }
      if (max(max(rgb.r, rgb.g), max(rgb.b, al)) < .002) discard;
      gl_FragColor = vec4(rgb, al);
    }
